#define WOT_CLIENT_REPLICA_HOST_BUILD
#include "stock_native_client_state.cpp"
#include "stock_native_client_drive_peers.cpp"
namespace {namespace d=stock_native_client_drive;namespace p=stock_native_bot_python;namespace cs=stock_native_client_state;
d::PlayerDescriptor descriptor(PyObject*params,PyObject*tuning){d::PlayerDescriptor out;auto&v=out.motion;auto&law=v.drive;const char*keys[]={"GRAVITY","GRAVITY_FACTOR","COHESION","COH_DECAY_Y","COH_DECAY_FACTOR","COH_DECAY_POW","SLOPE_COH_DECAY_Y","SLOPE_COH_DECAY","COH_DECAY_BOUND","POWER_FACTOR","BKWD_POWER_FRACTION","ENGINE_MIN_V","DRIVE_TRACTION","SLOPE_GRIP_LNG_MIN_Y","SLOPE_GRIP_LNG_FULL_Y","SLOPE_GRIP_LNG_MIN","SLOPE_GRIP_LNG_FULL","STEER_RESIST_MULT","SLIDE_HOLD_TAN","SLIDE_KINETIC","SLIP_THRESHOLD_TAN","SLIP_DRAG","COAST_BRAKE_SHARE","OVERSPEED_MAX_FACTOR","ANG_ACCELERATION_TIME","SPEED_AFFECT_ROT_DECREASE"};for(unsigned i=0;i<26;++i)law.t[i]=p::numeric(tuning,keys[i]);double*fields[]={&law.mass,&law.power,&law.ratio,&law.forward,&law.reverse,&law.friction,&law.brake,&law.rotation};const char*names[]={"mass","powerW","nativePowerRatio","speedFwd","speedBwd","specificFriction","brakeDecel","rotSpd"};for(unsigned i=0;i<8;++i)*fields[i]=p::numeric(params,names[i]);auto terrain=p::value(params,"terrainResist");const auto resistance=p::numbers<3>(terrain.get());std::copy(resistance.begin(),resistance.end(),law.terrain);v.side_min_y=p::numeric(tuning,"SLOPE_GRIP_SDW_MIN_Y");v.side_full_y=p::numeric(tuning,"SLOPE_GRIP_SDW_FULL_Y");v.side_min=p::numeric(tuning,"SLOPE_GRIP_SDW_MIN");v.side_full=p::numeric(tuning,"SLOPE_GRIP_SDW_FULL");v.constraint_iterations=int(p::integral(tuning,"SERVER_PHYSICS_CONSTRAINT_ITERATIONS"));return out;}
PyObject*predict(PyObject*,PyObject*args){try{PyObject*params,*tuning,*state,*shape,*impulses;double stamp,now;if(!PyArg_ParseTuple(args,"OOOOddO",&params,&tuning,&state,&shape,&stamp,&now,&impulses))return nullptr;std::vector<std::array<double,4>>rows;for(Py_ssize_t i=0;i<p::size(impulses);++i){auto row=p::item(impulses,i);rows.push_back(p::numbers<4>(row.get()));}const auto result=d::predictContactVelocity(descriptor(params,tuning),cs::read(state),p::numbers<4>(shape),stamp,now,rows,p::numeric(tuning,"SERVER_PHYSICS_STEP"));return p::tupleNumbers(result).release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_RuntimeError,e.what());return nullptr;}}
PyObject*history(PyObject*,PyObject*args){try{PyObject*raw;double cursor;long player;if(!PyArg_ParseTuple(args,"Odl",&raw,&cursor,&player))return nullptr;cs::Actor actor;for(Py_ssize_t i=0;i<p::size(raw);++i){auto value=p::item(raw,i);cs::Sample sample;sample.state=cs::read(value.get());sample.time=sample.state.get("time_us").numeric();sample.revision=std::int64_t(sample.state.get("revision").numeric());unsigned axis=0;for(const char*key:{"x","y","z","yaw","pitch","roll","aim_yaw","gun_pitch"})sample.value[axis++]=sample.state.get(key).numeric();actor.receipts.push_back(std::move(sample));}const auto out=d::historicalMotion(actor,cursor,player);if(!out)Py_RETURN_NONE;auto result=p::dict();p::set(result.get(),"velocity",p::tupleNumbers(out->velocity));p::set(result.get(),"witness",out->witness?p::tupleNumbers(*out->witness):p::retain(Py_None));return result.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_RuntimeError,e.what());return nullptr;}}
PyObject*histories(PyObject*,PyObject*args){try{PyObject*raw,*cursors;long player;if(!PyArg_ParseTuple(args,"OOl",&raw,&cursors,&player))return nullptr;cs::Actor actor;for(Py_ssize_t i=0;i<p::size(raw);++i){auto value=p::item(raw,i);cs::Sample sample;sample.state=cs::read(value.get());sample.time=sample.state.get("time_us").numeric();sample.revision=std::int64_t(sample.state.get("revision").numeric());unsigned axis=0;for(const char*key:{"x","y","z","yaw","pitch","roll","aim_yaw","gun_pitch"})sample.value[axis++]=sample.state.get(key).numeric();actor.receipts.push_back(std::move(sample));}auto result=p::list();for(Py_ssize_t i=0;i<p::size(cursors);++i){auto cursor=p::item(cursors,i);const auto out=d::historicalMotion(actor,p::scalar(cursor.get()),player);if(!out){p::append(result.get(),p::retain(Py_None));continue;}auto row=p::dict();p::set(row.get(),"velocity",p::tupleNumbers(out->velocity));p::set(row.get(),"witness",out->witness?p::tupleNumbers(*out->witness):p::retain(Py_None));p::append(result.get(),row);}return result.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_RuntimeError,e.what());return nullptr;}}
PyMethodDef methods[]={{"histories",histories,METH_VARARGS,""},{"predict",predict,METH_VARARGS,""},{"history",history,METH_VARARGS,""},{nullptr,nullptr,0,nullptr}};
}
extern "C" void initclient_drive_peers_test(){Py_InitModule("client_drive_peers_test",methods);}
